centers=[('historica','Centro de investigación histórica','Explicar cambios sin confundir secuencia, causa y juicio retrospectivo.',['Contrastar fuentes primarias y síntesis','Distinguir fecha, período y controversia','Conectar procesos globales con casos locales']),('economica','Centro de análisis económico','Leer producción, finanzas públicas y comercio sin confundir agregados con bienestar.',['Comparar unidad, precio y año','Examinar distribución y cobertura institucional','Explicitar supuestos antes de interpretar tendencias']),('geografica','Centro de investigación geográfica','Estudiar territorios, movilidad y redes con escalas cartográficas explícitas.',['Situar procesos y no solo fronteras','Comparar escalas y proyecciones','Relacionar territorio con actividad humana']),('cientifica','Centro de investigación científica','Conectar mecanismos, evidencia y límites de modelos científicos.',['Separar hipótesis, medición y explicación','Identificar incertidumbre y condiciones de validez','Reproducir razonamientos sin simular evidencia']),('recursos','Centro de recursos naturales','Investigar flujos materiales, alimentos y energía junto a sus costes ecológicos.',['Distinguir existencias de flujos','Medir presiones sin reducirlas a un ranking','Integrar gobernanza y servicios ecosistémicos']),('tecnologia','Centro de tecnología','Analizar sistemas técnicos, capacidades industriales y redes críticas.',['Examinar ciclo de vida y dependencias','Separar adopción de capacidad de innovación','Evaluar fiabilidad, acceso y mantenimiento']),('demografica','Centro de estudios demográficos','Explicar el cambio poblacional con estructura por edades y supuestos visibles.',['Distinguir tasas de recuentos','Leer cohortes y transiciones','No tratar proyecciones como destinos inevitables']),('civilizaciones','Centro de civilizaciones','Comparar sociedades a partir de instituciones, subsistencia y evidencia material.',['Usar cronologías aproximadas declaradas','Evitar jerarquías de progreso universal','Reconocer continuidad y diversidad interna']),('desarrollo','Centro de desarrollo mundial','Relacionar bienestar, educación, instituciones y condiciones urbanas.',['Leer promedios junto a desigualdades','Comparar períodos y no solo posiciones','Reconocer lagunas de cobertura'])]
